    public var from: String?
    public var to: String
    public var nonce: UInt64?
    public var chainId: UInt64
    public var data: Data
    public var signature: SignatureData?
    public var hash: Data?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(type: TransactionType, from: String?, to: String, nonce: UInt64?, chainId: UInt64, data: Data, signature: SignatureData?, hash: Data?) {
        self.type = type
        self.from = from
        self.to = to
        self.nonce = nonce
        self.chainId = chainId
        self.data = data
        self.signature = signature
        self.hash = hash
    }
}

#if compiler(>=6)
extension Transaction: Sendable {}
#endif


extension Transaction: Equatable, Hashable {
    public static func ==(lhs: Transaction, rhs: Transaction) -> Bool {
        if lhs.type != rhs.type {
            return false
        }
        if lhs.from != rhs.from {
            return false
        }
        if lhs.to != rhs.to {
            return false
        }
        if lhs.nonce != rhs.nonce {
            return false
        }
        if lhs.chainId != rhs.chainId {
            return false
        }
        if lhs.data != rhs.data {
            return false
        }
        if lhs.signature != rhs.signature {
            return false
        }
        if lhs.hash != rhs.hash {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(type)
        hasher.combine(from)
        hasher.combine(to)
        hasher.combine(nonce)
        hasher.combine(chainId)
        hasher.combine(data)
        hasher.combine(signature)
        hasher.combine(hash)
    }
}



#if swift(>=5.8)
