public struct FfiConverterTypeTransaction: FfiConverterRustBuffer {
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Transaction {
        return
            try Transaction(
                type: FfiConverterTypeTransactionType.read(from: &buf), 
                from: FfiConverterOptionString.read(from: &buf), 
                to: FfiConverterString.read(from: &buf), 
                nonce: FfiConverterOptionUInt64.read(from: &buf), 
                chainId: FfiConverterUInt64.read(from: &buf), 
                data: FfiConverterData.read(from: &buf), 
                signature: FfiConverterOptionTypeSignatureData.read(from: &buf), 
                hash: FfiConverterOptionData.read(from: &buf)
        )
    }

    public static func write(_ value: Transaction, into buf: inout [UInt8]) {
        FfiConverterTypeTransactionType.write(value.type, into: &buf)
        FfiConverterOptionString.write(value.from, into: &buf)
        FfiConverterString.write(value.to, into: &buf)
        FfiConverterOptionUInt64.write(value.nonce, into: &buf)
        FfiConverterUInt64.write(value.chainId, into: &buf)
        FfiConverterData.write(value.data, into: &buf)
        FfiConverterOptionTypeSignatureData.write(value.signature, into: &buf)
        FfiConverterOptionData.write(value.hash, into: &buf)
    }
}


