extension DidEvents: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDidEvents: FfiConverterRustBuffer {
    typealias SwiftType = DidEvents

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DidEvents {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .attributeChangedEvent(event: try FfiConverterTypeDidAttributeChanged.read(from: &buf)
        )
        
        case 2: return .delegateChanged(event: try FfiConverterTypeDidDelegateChanged.read(from: &buf)
        )
        
        case 3: return .ownerChanged(event: try FfiConverterTypeDidOwnerChanged.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DidEvents, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .attributeChangedEvent(event):
            writeInt(&buf, Int32(1))
            FfiConverterTypeDidAttributeChanged.write(event, into: &buf)
            
        
        case let .delegateChanged(event):
            writeInt(&buf, Int32(2))
            FfiConverterTypeDidDelegateChanged.write(event, into: &buf)
            
        
        case let .ownerChanged(event):
            writeInt(&buf, Int32(3))
            FfiConverterTypeDidOwnerChanged.write(event, into: &buf)
            
        }
    }
}


